    "pub_date": "2026-08-31 08:14:58",
    "author": "",
    "description": "今年以来，公募FOF发行明显回暖。数据显示，截至8月28日，年内共有131只FOF成立，合计募集约1375亿元，已超过过去2023年至2025年的募集规模总和。从发行质量看，今年新发FOF的募集规模中位数、平均募集规模均较往年明显提高，募集规模超过10亿元的产品达到46只。此外，今年发行的大规模FOF产品数量显著增加，显示FOF发行回暖并非仅由少数爆款推动。（证券时报）",
    "content": "今年以来，公募FOF发行明显回暖。数据显示，截至8月28日，年内共有131只FOF成立，合计募集约1375亿元，已超过过去2023年至2025年的募集规模总和。从发行质量看，今年新发FOF的募集规模中位数、平均募集规模均较往年明显提高，募集规模超过10亿元的产品达到46只。此外，今年发行的大规模FOF产品数量显著增加，显示FOF发行回暖并非仅由少数爆款推动。（证券时报）"
