    "content": "新华社南京8月30日电（记者杨绍功、李光正）8月30日上午10点，金鸡湖畔的苏州当代美术馆正式开门迎客。一早排成长队的参观者鱼贯而入。 人群中，年届六旬的苏州市民黄长明神情振奋。他说自己不擅长写写画画，却非常喜欢艺术作品，“现在身边有了这么大的美术馆，还能看到大师级的展览，机会十分难得，哪怕排长队也要一睹为快。” 苏州当代美术馆坐落于苏州工业园区右岸街99号，总建筑面积5.95万平方米，展厅面积约1.13万平方米，由九座独栋建筑组成，是目前长三角体量最大的当代美术馆。这座文化新地标的亮相，正是苏州这幅“双面绣”上落…"
