    "content": "快科技8月31日消息， 昨日，美国国家航空航天局表示，SpaceX与NASA推迟原定飞往国际空间站的任务发射。 由于在发射前的常规航天器处理流程中，在龙飞船推进系统上检测到氧化剂泄漏。因此，NASA与SpaceX决定调整Crew-13载人航天任务前往国际空间站的发射时间。 目前，联合团队正进行额外测试与数据评审，并在发射前完成所有必要修复工作，新的具体发射日期将另行公布。 Crew-13任务沿用四名乘员的标准配置，其中NASA宇航员杰西卡·沃特金斯担任指令长，卢克·德莱尼担任驾驶员。加拿大航天局宇航员约书亚·库特里…"
