    "author": "",
    "description": "",
    "content": "快科技8月31日消息， 苏州知芯传感技术有限公司正式推出公版MEMS微镜大阵列芯片。此举标志着我国在光交换核心器件领域实现关键性突破，全光交换（OCS）国产化进程迈出实质性一步。 业内专家指出， 该芯片的问世，将有效打破海外长期垄断，为全光互联的自主可控提供坚实底层支撑，尤其对AI算力基础设施的安全、稳定、可持续发展具有重要意义。 全光交换芯片是AI算力集群实现高效光互联的核心部件，此前长期由海外少数企业主导。 知芯传感自2019年成立以来，始终聚焦MEMS微镜赛道，确立“自研芯片、自主工艺、自建产线”的发展战略，…"
