    "content": "当我第一次从电视上看到这条消息：“中国西藏日喀则地区吉隆县吉隆口岸因尼泊尔泥石流灾害，人员遭受重大伤亡”——不禁惊呆了。我立即在网上搜索、询问吉隆口岸的情况，我方人员伤亡的情况如何？吉隆口岸是否已经被摧毁？后来终于得到了确切的消息，吉隆口岸已经不复存在，遭到了毁灭性的泥石流覆盖。从网上传播的各种视频可以看到，这场忽如其来的巨大灾变，已经使得山河改观，西藏西南边境线上的明珠——吉隆口岸，连同那座美丽的小镇吉隆镇，遭到毁灭性的冲击。中尼两国的边界界河——吉隆藏布上那座“中尼友谊桥”也被摧毁，被泥石流的浊浪所吞没。 我的…"
