    "content": "新华社洛杉矶8月30日电（记者高山）美国国家公园管理局30日说，位于亚利桑那州的大峡谷国家公园29日突发山洪，目前有超过20人被列为可能失联或下落不明人员。 国家公园管理局在一份声明中表示，截至30日早晨，山洪影响区域已撤出62人，稍晚会安排更多人员撤离。声明呼吁公众提供可能身处受灾区的徒步旅行人员或者预定露营地人员的信息。大峡谷国家公园工作人员正与亚利桑那州地方机构协调，持续开展疏散和应急救援工作。 据悉，山洪对包括光明天使峡谷在内的公园部分地区基础设施造成严重破坏，工作人员仍在持续评估受损情况。公园部分地区已关…"
