    "description": "30/08/2026 - 23:40 香港独立书店“留下书舍”周日（8月30日）迎来最后一个营业日。大批市民排队进入店内，与店员交谈、选购书籍，向即将关闭的书店告别。该书店7月曾因涉嫌出售煽动性书籍遭警方搜查。经营者表示，决定关门停业还与经营状况不佳、财务压力及香港整体社会环境有关。 路透社报道，周日，位于香港九龙的“留下书舍”外排起蜿蜒人龙，队伍一直延伸至楼梯间。这家面积约56平方米的书店，每次仅允许20名顾客进入。 香港独立书店一度…",
    "content": "30/08/2026 - 23:40 香港独立书店“留下书舍”周日（8月30日）迎来最后一个营业日。大批市民排队进入店内，与店员交谈、选购书籍，向即将关闭的书店告别。该书店7月曾因涉嫌出售煽动性书籍遭警方搜查。经营者表示，决定关门停业还与经营状况不佳、财务压力及香港整体社会环境有关。 路透社报道，周日，位于香港九龙的“留下书舍”外排起蜿蜒人龙，队伍一直延伸至楼梯间。这家面积约56平方米的书店，每次仅允许20名顾客进入。 香港独立书店一度蓬勃发展，但北京2020年在香港实施《香港国安法》后，独立书店数量迅速减少。 与…"
