    "content": "30/08/2026 - 23:06 法新社报道，佩古拉在两盘比赛中都两次破掉鲁塞的发球局，最终以6-3、6-2获胜。 尽管比分看似轻松，但过程并非一帆风顺。 作为一名32岁的老将，她在阿瑟·阿什球场这座巨大的主球场打揭幕战时，还是感受到了不小的压力。 佩古拉化解了自己面临的唯一一个破发点，但在首盘比赛中，她的紧张情绪显露无遗，在14次破发机会中仅把握住了两次。但两次破发助她获胜；她在第二盘的破发效率更高，4次机会中成功兑现了两次。她凭借一记干脆利落的正手底角制胜分拿到三个赛点；尽管鲁塞随后凭借强力发球挽救了两个赛…"
