    "pub_date": "2026-08-31 05:14:56",
    "author": "addou",
    "description": "手里一款华为旧手机，用的鸿蒙 3.0 ，在支付宝里面开通了一张 NFC 交通卡，现在每天上下班地铁就用这张卡，体验不错。支付宝时不时的有碰一碰红包，领了后可以去超市使用。问题出现了：使用碰一碰红包支付时，前两次总是跳转到 NFC 交通卡页面，不能自动识别，需重复几次才能自动付款交易成功。。。。。。目前没找到问题原因解决的方法。",
    "content": "手里一款华为旧手机，用的鸿蒙 3.0 ，在支付宝里面开通了一张 NFC 交通卡，现在每天上下班地铁就用这张卡，体验不错。支付宝时不时的有碰一碰红包，领了后可以去超市使用。问题出现了：使用碰一碰红包支付时，前两次总是跳转到 NFC 交通卡页面，不能自动识别，需重复几次才能自动付款交易成功。。。。。。目前没找到问题原因解决的方法。"
