    "content": "新华社雅典8月30日电（记者刘白云 陈刚）尼科西亚消息：塞浦路斯官员30日说，当天下午在塞北部海域发生的客轮倾覆事故已致7人死亡，另有23人失联。 塞当地官员向媒体说，倾覆客轮共载有267人，包括259名乘客和8名船员，其中237人已获救。由于前一日天气恶劣，港务部门并未批准客轮出港。该船自行驶离港口后，在塞北部凯里尼亚附近海域倾覆。船长发现船头进水后曾试图返航，但未能成功。 现场画面显示，客轮倾覆后，大量身穿救生衣的乘客漂浮在海面上等待救援。当地媒体报道说，船体老化是导致船体进水的主要原因。事故发生后，当地海岸警…"
