    "content": "新华社突尼斯8月30日电（记者周昊瑾）的黎波里消息：利比亚“4+4”委员会30日在首都的黎波里联合国利比亚支助团（联利支助团）总部签署协议，重组全国高级选举委员会理事会，并就总统和议会选举框架达成共识。 根据协议，相关选举应在协议生效后24个月内举行。选举须在统一行政权和统一国家机构下举行，若无法实现则将另建替代机制。 协议规定，国民代表大会和国家最高委员会须在协议签署之日起一个月内批准协议，否则将寻求联合国安理会等批准途径。 利比亚总统委员会主席曼菲和国家最高委员会主席塔卡拉虽受邀出席，但均未到场。塔卡拉称“4+…"
