    "content": "30/08/2026 - 17:50 美国宇航局（NASA）周日发射了“罗曼”太空望远镜，该望远镜旨在绘制宇宙地图。这项历时数年的任务旨在揭开一些最重大的物理谜团。 据美国航天局发布的视频直播显示，这台尖端设备于07时26分（格林尼治标准时间11时26分）由SpaceX公司的“猎鹰重型”火箭从佛罗里达州肯尼迪航天中心发射升空。 法新社说，这台望远镜历时十余年研发，耗资超过40亿美元，其命名是为了纪念美国最杰出的天文学家之一，南希·格蕾丝·罗曼，她被誉为“哈勃之母”，而“哈勃”正是美国宇航局另一台标志性望远镜的名称。…"
