    "content": "新华社上海8月30日电（记者杨有宗）香港大学上海张江基地二期项目8月30日在张江科学城启用，进一步拓展学校的教学科研与学生生活空间。 据介绍，张江基地二期项目新增人工智能实验室、研究与合作实验室、智能计算研究院、教学合作实验室等教学科研功能。此外，二期项目还将进一步拓展学生校园生活空间，提供运动、互动、共创及多元校园活动场景。 香港大学人工智能与数据科学工程学士项目大二学生孔策大一阶段在香港学习，新学期伊始，他来到上海，开启一段新的学习旅程。“张江基地完善的科研平台与校园环境，能够让我们近距离接触前沿科研资源，我也…"
