    "content": "IT之家 8 月 30 日消息，IMAX，简单来说就是“巨幕电影”，以超大银幕、高分辨率影像和定制化沉浸式音响著称。 据央视财经报道，今年暑期档，优质大片供给充足，消费者对高品质观影体验的需求集中释放，带动高端放映市场强势增长。其中 IMAX 票房同比增长近四成， 创下进入中国 25 年来的最强暑期档纪录 。 数据显示，截至 8 月 29 日， IMAX 中国暑期档票房突破 7.23 亿元人民币，同比增长 39% 。 其中进口片《 奥德赛 》以 3.1 亿元 IMAX 票房登顶暑期档冠军，IMAX 票房占影片全国总…"
