    "content": "新华社贵阳8月30日电 题：2026数博会映照“十五五”数字经济发展新图景 新华社记者向定杰、高亢 2026中国国际大数据产业博览会30日落下帷幕。自2015年创办以来，历经12年演变，数博会已成为观察我国数字经济发展的一扇窗口。 本届数博会以“词元——数据要素价值释放新路径”为年度主题，聚焦成果展示、行业交流、展产融合，举办各类活动89场，共吸引1.6万余名嘉宾注册参会，观展人数超过9万人次。372家中外企业齐聚参展，展出新技术、新产品1100余项。 机器人冲泡咖啡、大模型推演工厂产销……观众漫步各个展馆，近距离…"
