    "description": "磨憨镇磨龙村因洪涝灾害受损的农田与房屋（无人机照片，8月30日摄）。新华社记者 胡超 摄 新华社昆明8月30日电（记者严勇、孙敏）记者8月30日从昆明市防汛抗旱指挥部办公室和磨憨—磨丁经济合作区应急指挥中心获悉，受29日强降雨影响，磨憨镇已紧急组织转移8115人。相关部门紧急调拨各类救援物资运至集中安置点，各类生活物资保障到位，可满足集中安置点群众需求。 受持续强降雨影响，昆明市防汛抗旱指挥部8月29日14时30分起，对磨憨—磨丁经济合…",
    "content": "磨憨镇磨龙村因洪涝灾害受损的农田与房屋（无人机照片，8月30日摄）。新华社记者 胡超 摄 新华社昆明8月30日电（记者严勇、孙敏）记者8月30日从昆明市防汛抗旱指挥部办公室和磨憨—磨丁经济合作区应急指挥中心获悉，受29日强降雨影响，磨憨镇已紧急组织转移8115人。相关部门紧急调拨各类救援物资运至集中安置点，各类生活物资保障到位，可满足集中安置点群众需求。 受持续强降雨影响，昆明市防汛抗旱指挥部8月29日14时30分起，对磨憨—磨丁经济合作区启动防汛重大级（Ⅱ级）应急响应，组织危险区域群众紧急转移安置。目前，解放军和…"
