    "content": "“谁饮尼罗水，他日必重归。” 2016年访问埃及时，习近平主席引用这句埃及谚语表达重访埃及的心情，并寄语中埃友谊、中阿友好“像尼罗河水般奔涌向前”。 今年是中埃建交70周年。时隔10年，习近平主席即将对埃及进行国事访问。 近年来，在习近平主席的关心和支持下，中埃人文交流异彩纷呈。从联合考古到互办展览，从典籍互译到青年交流，中埃人民互学互鉴，共同书写相知相亲、美美与共的动人故事。 书写民心相通故事 2016年1月20日，在埃及首都开罗，习近平主席会见了10名获得“中国阿拉伯友好杰出贡献奖”的友好人士，同他们一一握手，…"
