    "pub_date": "2026-08-30 21:10:49",
    "author": "陈刚",
    "description": "新华社雅典8月30日电（记者刘白云 陈刚）尼科西亚消息：据塞浦路斯媒体报道，一艘客轮30日下午在塞北部附近海域倾覆，目前已造成6人死亡，172人获救，大规模搜救行动正在进行中。 另据《塞浦路斯邮报》报道，该客轮当时正在塞北部凯里尼亚附近海域航行，事发地点距离凯里尼亚海岸约2公里，事发时有270余人落水。当地政府官员说，客轮船长发现船头进水后曾试图返航，但未能成功。 事故发生后，当地海岸警卫队搜救人员迅速赶赴现场，附近多艘船只也前往事发海…",
    "content": "新华社雅典8月30日电（记者刘白云 陈刚）尼科西亚消息：据塞浦路斯媒体报道，一艘客轮30日下午在塞北部附近海域倾覆，目前已造成6人死亡，172人获救，大规模搜救行动正在进行中。 另据《塞浦路斯邮报》报道，该客轮当时正在塞北部凯里尼亚附近海域航行，事发地点距离凯里尼亚海岸约2公里，事发时有270余人落水。当地政府官员说，客轮船长发现船头进水后曾试图返航，但未能成功。 事故发生后，当地海岸警卫队搜救人员迅速赶赴现场，附近多艘船只也前往事发海域协助救援。目前受伤人员已被送医救治。 事故具体原因正在调查中。"
