    "content": "（来源：麻省理工科技评论） 美国电动车卖不动了。 目前，电动车在美国新车销量中的占比还不到 10%，而且这个数字仍在下降。从气候角度看，这显然不是什么好消息，毕竟交通运输业仍是美国最大的温室气体排放来源。 Slate Auto 的新款电动皮卡，或许提供了一种不同的思路。至少，它几乎反着美国汽车市场的主流逻辑来：不追求配置堆满，也不追求越来越长的续航，而是把车做得更小、更简单，也更便宜。 Slate 把“简单”做到了近乎极致。这是一辆只有两个车门的小型皮卡，车身甚至比本田思域还短。此前不少媒体最津津乐道的一点，是基础…"
